    private func request<Params: Encodable, Response: Decodable>(
        _ method: String, _ params: Params, _ timeout: TimeInterval?
    ) async throws -> Response {
        let raw = try await transport.call(method, params: JSONValue.encode(params), timeout: timeout)
        do {
            return try raw.decode(Response.self)
        } catch {
            throw GatewayDecodingError(method: method, raw: raw, underlying: error)
        }
    }
